"""出征准备 — 补给与战役支援。

提供补给 / 支援状态查询与切换操作。
"""

from __future__ import annotations

from typing import TYPE_CHECKING

from autowsgr.infra.exceptions import PageDriftError
from autowsgr.infra.logger import get_logger
from autowsgr.types import PageName
from autowsgr.ui.battle.base import BaseBattlePreparation, Panel
from autowsgr.ui.battle.constants import (
    CLICK_SHIP_SLOT,
    CLICK_SUPPORT,
    SUPPORT_DISABLE,
    SUPPORT_ENABLE,
    SUPPORT_EXHAUSTED,
    SUPPORT_PROBE,
)
from autowsgr.ui.stack import record_page_substate
from autowsgr.ui.substate import SubstateSpec
from autowsgr.ui.utils import NavConfig, NavigationError, act_and_wait, click_and_wait_for_page
from autowsgr.vision import PixelChecker


if TYPE_CHECKING:
    import numpy as np


_log = get_logger('ui.preparation')


class SupplyMixin(BaseBattlePreparation):
    """补给与战役支援 Mixin。

    依赖 :class:`~autowsgr.ui.battle.base.BaseBattlePreparation` 提供的
    ``_ctrl``, ``select_panel``, ``is_auto_supply_enabled``。
    """

    # ── 状态查询 — 战役支援 ──────────────────────────────────────────────

    @staticmethod
    def is_support_enabled(screen: np.ndarray) -> bool:
        """检测战役支援是否启用。灰色 (次数用尽) 也视为已启用。"""
        x, y = SUPPORT_PROBE
        pixel = PixelChecker.get_pixel(screen, x, y)
        d_enable = pixel.distance(SUPPORT_ENABLE)
        d_disable = pixel.distance(SUPPORT_DISABLE)
        d_exhausted = pixel.distance(SUPPORT_EXHAUSTED)
        if d_enable > d_exhausted and d_disable > d_exhausted:
            return True
        return d_enable < d_disable

    # ── 动作 — 开关 ──────────────────────────────────────────────────────

    @staticmethod
    def _support_probe_available(screen: np.ndarray) -> bool:
        """战役支援的开/关探针是否可判定。

        次数用尽时探测点是灰色，``is_support_enabled`` 按既有语义把它当作
        「已启用」，但无法可靠区分开/关。此时返回 ``False``，让
        :class:`~autowsgr.ui.substate.SubstateSpec` 走「点一次 + warning」
        的降级，而不是误判并重试。
        """
        x, y = SUPPORT_PROBE
        pixel = PixelChecker.get_pixel(screen, x, y)
        d_enable = pixel.distance(SUPPORT_ENABLE)
        d_disable = pixel.distance(SUPPORT_DISABLE)
        d_exhausted = pixel.distance(SUPPORT_EXHAUSTED)
        return not (d_exhausted <= d_enable and d_exhausted <= d_disable)

    def toggle_battle_support(self) -> None:
        """切换战役支援开关，并验证开/关状态确实翻转。

        灰色（次数用尽）时探针不可判定，保留旧行为：点一次 + warning。
        """
        screen = self._ctrl.screenshot()
        desired = not self.is_support_enabled(screen)
        SubstateSpec(
            page=PageName.BATTLE_PREP.value,
            substate='战役支援/开' if desired else '战役支援/关',
            checker=lambda screen: self.is_support_enabled(screen) == desired,
            timeout=1.5,
            retries=1,
            interval=0.25,
            stable_frames=2,
            probe=self._support_probe_available,
        ).click(
            self._ctx,
            CLICK_SUPPORT,
            source='出征准备-战役支援',
            action_name='toggle_battle_support',
        )

    # ── 动作 — 补给 ──────────────────────────────────────────────────────

    _SUPPLY_TARGET = '出征准备-快速补给'
    _SUPPLY_SLOT_CONFIG = NavConfig(
        max_retries=1,
        timeout=1.5,
        interval=0.3,
        stable_frames=1,
    )
    """单个槽位点击后的状态复核配置（不重复点击槽位）。"""

    def _is_quick_supply_ready(self, screen: np.ndarray) -> bool:
        """当前是否仍稳定停留在快速补给面板。

        探针不可用（``get_active_panel`` 返回 ``None``）时只要求仍在出征
        准备页 —— 与 :meth:`select_panel` 的降级策略一致，无法验证不等于
        必然失败，但日志会保留 warning。
        """
        if not BaseBattlePreparation.is_current_page(screen).matched:
            return False
        active = self.get_active_panel(screen)
        return active is None or active is Panel.QUICK_SUPPLY

    def supply(self, ship_ids: list[int] | None = None) -> None:
        """切换到补给面板并补给指定舰船。

        每次点击舰船槽位后都复核「仍在快速补给面板」；离开面板（弹窗/
        资源不足/误触）立即失败，不再带着错误画面继续点下一个槽位。
        """
        if ship_ids is None:
            ship_ids = [0, 1, 2, 3, 4, 5]
        self.select_panel(Panel.QUICK_SUPPLY)
        for sid in ship_ids:
            if sid not in CLICK_SHIP_SLOT:
                _log.warning('[UI] 无效槽位: {}', sid)
                continue
            click_and_wait_for_page(
                self._ctrl,
                click_coord=CLICK_SHIP_SLOT[sid],
                checker=self._is_quick_supply_ready,
                source=self._SUPPLY_TARGET,
                target=f'{self._SUPPLY_TARGET}/槽位{sid}',
                config=self._SUPPLY_SLOT_CONFIG,
                stop_event=self._ctx.stop_event,
            )
        record_page_substate(self._ctx, PageName.BATTLE_PREP, Panel.QUICK_SUPPLY.value)
        _log.debug('[UI] 出征准备 → 补给 {}', ship_ids)

    def apply_supply(self) -> None:
        """确保舰队已补给 (自动补给未开启则手动补给)。

        手动补给路径用 :func:`act_and_wait` 把「切换面板 + 逐槽点击」作为
        一个动作，动作结束后必须识别到快速补给面板；超时统一升为
        :class:`PageDriftError`。自动补给已开启时页面不发生子状态切换，
        只记录当前底部面板。
        """
        screen = self._ctrl.screenshot()
        if self.is_auto_supply_enabled(screen):
            active = self.get_active_panel(screen)
            if active is not None:
                record_page_substate(self._ctx, PageName.BATTLE_PREP, active.value)
            _log.debug('[UI] 出征准备 → 自动补给已开启, 跳过手动补给')
            return

        try:
            act_and_wait(
                self._ctrl,
                self.supply,
                self._is_quick_supply_ready,
                config=NavConfig(
                    max_retries=1,
                    timeout=2.0,
                    interval=0.3,
                    stable_frames=2,
                ),
                source=PageName.BATTLE_PREP.value,
                target=self._SUPPLY_TARGET,
                stop_event=self._ctx.stop_event,
            )
        except NavigationError as exc:
            raise PageDriftError(
                f'补给动作后未确认到达: {PageName.BATTLE_PREP.value} -> {self._SUPPLY_TARGET}',
                target=self._SUPPLY_TARGET,
                page_trail=[PageName.BATTLE_PREP.value, self._SUPPLY_TARGET],
                action_trail=['apply_supply()'],
                screen=self._ctrl.screenshot(),
            ) from exc

        record_page_substate(self._ctx, PageName.BATTLE_PREP, Panel.QUICK_SUPPLY.value)
